static const char calculator_css[] = "/* SPDX-License-Identifier: GPL-3.0-or-later\n * GTK3 adaptation of GNOME Calculator (libadwaita dark look).\n * Scoped to .embedded-calculator; no global screen provider. */\n.embedded-calculator { background-color: #222226; }\n.embedded-calculator button {\n  font-size: 1.1em; padding: 2px 4px; min-height: 0; min-width: 0;\n  border-radius: 8px; border: none; box-shadow: none; outline: none;\n  background-image: none; background-color: #38383c; color: #ffffff;\n  text-shadow: none; -gtk-icon-shadow: none;\n}\n.embedded-calculator button:hover { background-color: #424247; }\n.embedded-calculator button:active,\n.embedded-calculator button:checked { background-color: #4e4e53; }\n.embedded-calculator button.clear-button,\n.embedded-calculator button.number-button { font-size: 1.2em; font-weight: bold; }\n.embedded-calculator button.number-button { background-color: #4e4e51; }\n.embedded-calculator button.number-button:hover { background-color: #58585b; }\n.embedded-calculator button.number-button:active { background-color: #666669; }\n.embedded-calculator button.operator-button,\n.embedded-calculator button.suggested-action { font-size: 1.6em; }\n.embedded-calculator button.suggested-action { background-color: #3a944a; color: #ffffff; }\n.embedded-calculator button.suggested-action:hover { background-color: #43a053; }\n.embedded-calculator button.suggested-action:active { background-color: #338542; }\n.embedded-calculator button:disabled { color: rgba(255,255,255,.35); background-color: #38383c; }\n.embedded-calculator button.inverse-button { background-color: #2d3631; color: #83d48d; font-size: 1.1em; }\n.embedded-calculator button.inverse-button:hover { background-color: #34403a; }\n.embedded-calculator button.inverse-button:checked { background-color: #3d5c46; color: #a8f0b2; }\n";
